"""Order reconciliation pipeline (v1 contract).

Pure functions only: parses CSV *strings*, uses decimal fixed-point,
performs no file/network/process access.
"""

import csv
import io
import json
from decimal import Decimal, InvalidOperation


# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------

def _read_rows(csv_text, required_columns, kind):
    """Parse a CSV string into a list of dict rows (values are strings)."""
    if csv_text is None:
        raise ValueError("%s csv must not be None" % kind)
    if not isinstance(csv_text, str):
        raise ValueError("%s csv must be a string" % kind)
    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames is None:
        return []
    for col in required_columns:
        if col not in reader.fieldnames:
            raise ValueError("%s csv missing column: %s" % (kind, col))
    rows = []
    for raw in reader:
        row = {}
        for key, value in raw.items():
            if key is None:
                continue  # ignore extra unnamed columns
            row[key] = "" if value is None else value
        rows.append(row)
    return rows


def _dedupe(rows, id_field, kind):
    """Same id + identical row -> counted once; same id + any diff -> error."""
    seen = {}
    out = []
    for row in rows:
        rid = row.get(id_field, "").strip()
        if rid == "":
            raise ValueError("%s row missing %s" % (kind, id_field))
        signature = tuple(sorted((k, v.strip()) for k, v in row.items()))
        if rid in seen:
            if seen[rid] == signature:
                continue
            raise ValueError(
                "conflicting duplicate %s id %s" % (kind, rid)
            )
        seen[rid] = signature
        out.append(row)
    return out


def _amount_to_cents(raw, kind):
    """Parse a decimal amount string to integer cents (no float math)."""
    text = "" if raw is None else str(raw).strip()
    if text == "":
        raise ValueError("%s amount missing" % kind)
    try:
        value = Decimal(text)
    except InvalidOperation:
        raise ValueError("%s invalid amount: %r" % (kind, raw))
    if not value.is_finite():
        raise ValueError("%s non-finite amount: %r" % (kind, raw))
    if value < 0:
        raise ValueError("%s negative amount: %r" % (kind, raw))
    exponent = value.as_tuple().exponent
    if not isinstance(exponent, int) or exponent < -2:
        raise ValueError("%s amount has more than 2 decimals: %r" % (kind, raw))
    cents = (value * Decimal(100)).to_integral_exact()
    if not cents == cents.to_integral_value():
        raise ValueError("%s amount has more than 2 decimals: %r" % (kind, raw))
    return int(cents)


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def reconcile(orders_csv, refunds_csv, policy="v1", cutoff=None):
    """Reconcile orders against refunds per the v1 contract.

    Returns {"orders": [...], "customers": [...], "totals": {...}} with all
    amounts as integer cents.  ``cutoff`` is reserved for future policies
    and is ignored by v1.
    """
    if policy != "v1":
        raise ValueError("unsupported policy: %r" % (policy,))

    order_rows = _dedupe(
        _read_rows(orders_csv, ["order_id", "customer", "amount", "status"], "order"),
        "order_id",
        "order",
    )
    refund_rows = _dedupe(
        _read_rows(refunds_csv, ["refund_id", "order_id", "amount"], "refund"),
        "refund_id",
        "refund",
    )

    orders = {}
    for row in order_rows:
        oid = row["order_id"].strip()
        status = row["status"].strip().lower()
        if status not in ("paid", "cancelled"):
            raise ValueError("order %s has unknown status: %r" % (oid, row["status"]))
        paid_cents = _amount_to_cents(row["amount"], "order %s" % oid)
        orders[oid] = {
            "order_id": oid,
            "customer": row["customer"].strip(),
            "status": status,
            "paid_cents": paid_cents,
        }

    refund_cents_by_order = {}
    for row in refund_rows:
        oid = row["order_id"].strip()
        if oid not in orders:
            raise ValueError("refund %s references unknown order %s"
                             % (row["refund_id"].strip(), oid))
        if orders[oid]["status"] != "paid":
            raise ValueError("refund %s targets non-paid order %s"
                             % (row["refund_id"].strip(), oid))
        rc = _amount_to_cents(row["amount"], "refund %s" % row["refund_id"].strip())
        refund_cents_by_order[oid] = refund_cents_by_order.get(oid, 0) + rc

    for oid, rc in refund_cents_by_order.items():
        if rc > orders[oid]["paid_cents"]:
            raise ValueError(
                "order %s refunds (%d cents) exceed paid (%d cents)"
                % (oid, rc, orders[oid]["paid_cents"])
            )

    result_orders = []
    customer_totals = {}
    total_paid = 0
    total_refund = 0
    for oid in sorted(orders):
        order = orders[oid]
        if order["status"] != "paid":
            continue
        paid = order["paid_cents"]
        refund = refund_cents_by_order.get(oid, 0)
        net = paid - refund
        result_orders.append({
            "order_id": oid,
            "customer": order["customer"],
            "paid_cents": paid,
            "refund_cents": refund,
            "net_cents": net,
        })
        customer_totals[order["customer"]] = (
            customer_totals.get(order["customer"], 0) + net
        )
        total_paid += paid
        total_refund += refund

    customers = [
        {"customer": name, "net_cents": customer_totals[name]}
        for name in sorted(customer_totals)
    ]
    return {
        "orders": result_orders,
        "customers": customers,
        "totals": {
            "paid_cents": total_paid,
            "refund_cents": total_refund,
            "net_cents": total_paid - total_refund,
        },
    }


def export_bundle(result):
    """Serialize a reconcile result into a simple filename -> text bundle."""
    return {"summary.json": json.dumps(result, sort_keys=True)}
